// 1. 创建 Optional
Optional<String> name = Optional.of("Alice");        // 非空值
Optional<String> maybeNull = Optional.ofNullable(null); // 允许null
Optional<String> empty = Optional.empty();              // 空实例

// 2. 安全取值
String result = name.orElse("Default");           // "Alice"
String result2 = maybeNull.orElse("Default");     // "Default"
String result3 = maybeNull.orElseGet(() -> generateDefault()); // 惰性求值

// 3. 链式处理 - 传统方式 vs Optional
// 传统方式
String city = null;
if (user != null) {
    Address addr = user.getAddress();
    if (addr != null) {
        city = addr.getCity();
    }
}
// Optional 方式
String city = Optional.ofNullable(user)
    .map(User::getAddress)
    .map(Address::getCity)
    .orElse("Unknown");

// 4. filter 过滤
Optional<String> filtered = Optional.of("hello")
    .filter(s -> s.length() > 3);  // Optional[hello]
